// Real WASM with synthetic encrypted outputs, generated by the node repo's
// crates/zoka-pq-scan-wasm/examples/incoming_fixture.rs (public fixed seeds).
import { readFileSync } from "node:fs";
import { Buffer } from "node:buffer";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { initSync, Scanner } from "./scan-wasm/zoka_pq_scan_wasm.js";
import fixture from "../test/fixtures/incoming.json";

// Read from disk: under the DOM test environment `import.meta.url` is not a
// file URL. The tests run from the project root.
const compiled = initSync({
  module: readFileSync(resolve(process.cwd(), "src/lib/scan-wasm/zoka_pq_scan_wasm_bg.wasm")),
});

describe("the real view-key scanner", () => {
  it("wipes the encoded key buffer after decoding, including invalid keys", () => {
    for (const key of [fixture.full, fixture.incoming]) {
      const scanner = new Scanner(key, 2);
      try { expect(Buffer.from(compiled.memory.buffer).includes(Buffer.from(key))).toBe(false); }
      finally { scanner.free(); }
      expect(() => new Scanner(key + "x", 2)).toThrow("view key");
      expect(Buffer.from(compiled.memory.buffer).includes(Buffer.from(key + "x"))).toBe(false);
    }
  });

  it("keeps the full key's balance and outgoing history compatible", () => {
    const scanner = new Scanner(fixture.full, 2);
    try {
      expect(scanner.address()).toBe(fixture.address);
      expect(scanner.add_page(new Uint8Array(fixture.page))).toBe(5);
      expect(scanner.next()).toBe(6);
      const result = JSON.parse(scanner.balance());
      expect(result).toMatchObject({ kind: "full", height: 5, balance_atoms: 75, spendable_atoms: 63, immature_atoms: 12 });
      expect(result.sent).toHaveLength(2);
      expect(result.sent[0]).toMatchObject({ paid: 30, change: 69, fee: 1 });
    } finally { scanner.free(); }
  });

  it("counts incoming receipts, excludes tagged change and never invents a balance", () => {
    const scanner = new Scanner(` ${fixture.incoming}\n`, 2);
    try {
      expect(scanner.address()).toBe(fixture.address);
      scanner.add_page(new Uint8Array(fixture.page));
      const result = JSON.parse(scanner.balance());
      // The 58 of legacy change cannot be distinguished from a receipt.
      expect(result).toMatchObject({ kind: "incoming", height: 5, received_atoms: 175, change_atoms: 69, immature_atoms: 12 });
      expect(result).not.toHaveProperty("balance_atoms");
      expect(result).not.toHaveProperty("spendable_atoms");
      expect(result).not.toHaveProperty("sent");
      expect(result).not.toHaveProperty("sent_atoms");
      expect(result.received.find((r: { value: number }) => r.value === 69)).toMatchObject({ change: true, memo: "" });
      expect(result.received.find((r: { value: number }) => r.value === 58)).toMatchObject({ change: false });
      expect(result.received.find((r: { value: number }) => r.value === 5)).toMatchObject({ memo: "invoice", change: false });
      expect(() => scanner.add_page(new Uint8Array(fixture.page))).toThrow("does not follow");
    } finally { scanner.free(); }
  });

  it("rejects wrong networks, addresses, corrupt keys and corrupt pages for both scopes", () => {
    for (const key of [fixture.full, fixture.incoming]) {
      expect(() => new Scanner(key, 3)).toThrow("view key");
      expect(() => new Scanner(key + "x", 2)).toThrow("view key");
      const scanner = new Scanner(key, 2);
      try { expect(() => scanner.add_page(new Uint8Array([1, 2]))).toThrow("unreadable"); }
      finally { scanner.free(); }
    }
    expect(() => new Scanner(fixture.address, 2)).toThrow("view key");
  });
});
